{
  "packet_id": "H6-T04-1",
  "claim_id": "C035",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C035.component",
    "value": "If the joint predeclared benefit and guardrail requirement is not met, the existing experience should be retained.",
    "scope": "The fallback to the stated rollout gate, not a conclusion that the change has no benefit.",
    "provenance": {
      "refs": [
        {
          "source_id": "P021",
          "role": "SUPPORT"
        },
        {
          "source_id": "P022",
          "role": "SUPPORT"
        },
        {
          "source_id": "P028",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P021 states the joint rollout requirement; P022 explicitly directs retention otherwise. P028 supplies the qualification that insufficient evidence does not prove absence of benefit."
    }
  },
  "signal_basis": {
    "component_id": "C035.signal_basis",
    "value": "The release comparison does not satisfy the joint predeclared benefit and guardrail criteria, using publication outcomes and predefined guardrail measurements.",
    "scope": "Application of the stated rollout gate to release-comparison evidence, with publication rates assessed within a common window.",
    "provenance": {
      "refs": [
        {
          "source_id": "P009",
          "role": "SUPPORT"
        },
        {
          "source_id": "P017",
          "role": "SUPPORT"
        },
        {
          "source_id": "P021",
          "role": "SUPPORT"
        },
        {
          "source_id": "P022",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans specify advance thresholds, comparison measurements, the joint gate and its unmet-condition fallback."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C035.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "No unresolved empirical relation is needed to apply the explicitly stated decision rule."
    }
  },
  "rationale": "Failure to satisfy the joint gate licenses retaining the existing experience under the mapping's explicit decision policy. The claim requires neither proof that the change lacks benefit nor an inference that the existing experience is superior.",
  "uncertainty": "The change's actual benefit may remain unresolved; that uncertainty does not prevent applying the stated fallback.",
  "anomalies": []
}
